begin
  select id into _co from public.companies
   where lower(coalesce(code, '')) = 'italbike' or upper(coalesce(name, '')) like '%ITALBIKE%'
   order by created_at limit 1;
  if _co is null then
    raise notice 'Reprise tarif 15 : societe ITALBIKE STORE introuvable, rien a faire.';
    return;
  end if;

  -- ------------------------------------------------ 1. Tarif « 15 — REMISE 15 % »
  select id into _pl from public.price_lists where company_id = _co and lower(btrim(code)) = '15';
  if _pl is null then
    insert into public.price_lists (company_id, code, label, is_promo, show_discount, is_active)
    values (_co, '15', 'REMISE 15 %', false, true, true) returning id into _pl;
  end if;
  if not exists (select 1 from public.price_list_rules where price_list_id = _pl and scope = 'all') then
    insert into public.price_list_rules (company_id, price_list_id, scope, kind, tiers, note)
    values (_co, _pl, 'all', 'discount', '[{"min_qty": 1, "value": 15}]'::jsonb,
            'Repris de G8 : tarif par fournisseurs, ligne fournisseur « Tous », remise 15 %, remise affichee.');
  end if;

  foreach _code in array _tariff_codes loop
    _cid := null;
    select c.id into _cid from public.contacts c
     where c.company_id = _co and c.type <> 'fournisseur'
       and (c.legacy_code = _code or (c.legacy_code is null and c.code = _code))
     order by (c.legacy_code = _code) desc nulls last, c.created_at
     limit 1;
    if _cid is null then _missing := _missing || _code; continue; end if;
    update public.contacts set price_list_id = _pl where id = _cid and price_list_id is distinct from _pl;
  end loop;
  if cardinality(_missing) > 0 then
    raise notice 'Reprise tarif 15 : clients G8 introuvables (code) : %', array_to_string(_missing, ', ');
  else
    raise notice 'Reprise tarif 15 : les 4 clients sont rattaches au tarif 15.';
  end if;

  -- ------------------------------------------------ 2. Cases « A surveiller » / « Bloque »
  if not exists (select 1 from public.contacts where company_id = _co and imported_from = 'G8' and type <> 'fournisseur' and is_watch) then
    update public.contacts set is_watch = true
     where company_id = _co and imported_from = 'G8' and type <> 'fournisseur' and legacy_code = any(_watch) and not is_watch;
    get diagnostics _n = row_count;
    raise notice 'Reprise G8 : % client(s) a surveiller (sur %).', _n, cardinality(_watch);
  else
    raise notice 'Reprise G8 : « A surveiller » deja repris par l import, rien change.';
  end if;
  if not exists (select 1 from public.contacts where company_id = _co and imported_from = 'G8' and type <> 'fournisseur' and is_blocked) then
    update public.contacts set is_blocked = true
     where company_id = _co and imported_from = 'G8' and type <> 'fournisseur' and legacy_code = any(_blocked) and not is_blocked;
    get diagnostics _n = row_count;
    raise notice 'Reprise G8 : % client(s) bloque(s) (sur %).', _n, cardinality(_blocked);
  else
    raise notice 'Reprise G8 : « Bloque » deja repris par l import, rien change.';
  end if;

  -- ------------------------------------------------ 3. Categorie (GENERAL / INTERNET / vide)
  if not exists (select 1 from public.contacts where company_id = _co and imported_from = 'G8' and type <> 'fournisseur' and nullif(btrim(category), '') is not null) then
    update public.contacts set category = 'INTERNET'
     where company_id = _co and imported_from = 'G8' and type <> 'fournisseur' and legacy_code = any(_internet)
       and nullif(btrim(category), '') is null;
    get diagnostics _n = row_count;
    raise notice 'Reprise G8 : % client(s) en categorie INTERNET (sur %).', _n, cardinality(_internet);
    update public.contacts set category = 'GENERAL'
     where company_id = _co and imported_from = 'G8' and type <> 'fournisseur' and legacy_code is not null
       and not (legacy_code = any(_internet)) and not (legacy_code = any(_no_category))
       and nullif(btrim(category), '') is null;
    get diagnostics _n = row_count;
    raise notice 'Reprise G8 : % client(s) en categorie GENERAL (5 099 dans l export).', _n;
  else
    raise notice 'Reprise G8 : categories deja reprises par l import, rien change.';
  end if;
end $mig$;
